function drawCharacter(c,x,y,opt={}){const npc=!!opt.npc,scale=opt.scale||1;ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const color=npc?opt.shirt:look.color;ctx.fillStyle='#45584235';ctx.beginPath();ctx.ellipse(0,0,20,7,0,0,7);ctx.fill();let moving=!npc&&Math.abs(opt.step||0)>0;let swing=moving?Math.sin(opt.step)*3:0;ctx.fillStyle=npc?'#665b55':'#f0e2c9';ctx.beginPath();ctx.ellipse(-7,0+swing,6,4,0,0,7);ctx.ellipse(7,0-swing,6,4,0,0,7);ctx.fill();
