// neck and face
ctx.fillStyle=npc?opt.skin:'#f3cfb4';ctx.fillRect(-4,-43,8,9);ctx.fillStyle=npc?opt.skin:'#f3cfb4';ctx.beginPath();ctx.ellipse(0,-53,13,16,0,0,7);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(-5,-52,3.3,4,0,0,7);ctx.ellipse(5,-52,3.3,4,0,0,7);ctx.fill();ctx.fillStyle='#53625c';ctx.beginPath();ctx.ellipse(-4.4,-51,1.3,2.1,0,0,7);ctx.ellipse(5.6,-51,1.3,2.1,0,0,7);ctx.fill();ctx.fillStyle='#df9d91';ctx.beginPath();ctx.arc(-9,-47,2,0,7);ctx.arc(9,-47,2,0,7);ctx.fill();
