const hair=npc?opt.hair:['#785b58','#59443c','#c68c69','#604b69','#b77f77','#6b765d'][look.hair%6];ctx.fillStyle=hair||'#785b58';ctx.beginPath();ctx.ellipse(0,-62,14,9,0,Math.PI,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-13,-61);ctx.quadraticCurveTo(-16,-48,-11,-44);ctx.lineTo(-7,-51);ctx.lineTo(-7,-61);ctx.fill();ctx.beginPath();ctx.moveTo(12,-61);ctx.quadraticCurveTo(16,-48,11,-45);ctx.lineTo(7,-51);ctx.lineTo(7,-61);ctx.fill();if(!npc&&look.hair===2){ctx.strokeStyle=hair;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-62,14,Math.PI,Math.PI*2);ctx.stroke()}if(!npc&&look.hair===3){ctx.beginPath();ctx.ellipse(11,-67,7,5,-.4,0,7);ctx.fill()}
// accessories
if(!npc){if(look.accessory===1){ctx.fillStyle='#e99c94';for(let i=-2;i<=2;i++){ctx.beginPath();ctx.arc(i*6,-71-(i===0?2:0),4,0,7);ctx.fill()}ctx.fillStyle='#e9cf79';ctx.beginPath();ctx.arc(0,-71,2.3,0,7);ctx.fill()}if(look.accessory===2){ctx.fillStyle='#e7888a';ctx.beginPath();ctx.arc(10,-67,5,0,7);ctx.arc(16,-67,5,0,7);ctx.fill();ctx.fillStyle='#f4d184';ctx.beginPath();ctx.arc(13,-67,2.5,0,7);ctx.fill()}if(look.accessory===3){ctx.fillStyle='#e4c371';ctx.beginPath();ctx.moveTo(8,-66);ctx.lineTo(14,-70);ctx.lineTo(16,-62);ctx.lineTo(10,-61);ctx.fill()}if(look.accessory===4){ctx.strokeStyle='#776e67';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(-5,-52,4.2,0,7);ctx.arc(5,-52,4.2,0,7);ctx.moveTo(-1,-52);ctx.lineTo(1,-52);ctx.stroke()}}
