function drawPreview(){if(!preview||!preview.width)return;const w=preview.width,h=preview.height; pctx.setTransform(1,0,0,1,0,0);pctx.clearRect(0,0,w,h);const scale=Math.min(w/200,h/260);pctx.setTransform(scale,0,0,scale,w/2-100*scale,h/2-130*scale);const old=ctx; // render matching character using shared drawing context
ctx.save();ctx=pctx;drawCharacter(ctx,100,231,{scale:1});ctx.restore();ctx=old}

